import express from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

const SECRET = 'dev-only-secret-change-me-0123456789abcdef';
const app = express();
app.use(express.json());

const users = [
  { id: 1, email: 'asha@example.com', name: 'Asha', passwordHash: bcrypt.hashSync('password123', 10) },
  { id: 2, email: 'ravi@example.com', name: 'Ravi', passwordHash: bcrypt.hashSync('password456', 10) },
];
const notes = [
  { id: 1, userId: 1, text: "Asha's private note" },
  { id: 2, userId: 2, text: "Ravi's private note" },
];

app.post('/login', async (req, res) => {
  const user = users.find((u) => u.email === req.body.email);
  if (!user || !(await bcrypt.compare(req.body.password, user.passwordHash))) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  res.json({ token: jwt.sign({ sub: user.id }, SECRET, { expiresIn: '1h' }) });
});

function requireAuth(req, res, next) {
  const token = req.headers.authorization.split(' ')[1];
  const payload = jwt.decode(token);
  if (!payload) return res.status(401).json({ error: 'Invalid token' });
  req.userId = payload.sub;
  next();
}

app.get('/me', requireAuth, (req, res) => {
  res.json(users.find((u) => u.id === req.userId));
});

app.get('/notes/:id', requireAuth, (req, res) => {
  const note = notes.find((n) => n.id === Number(req.params.id));
  if (!note) return res.status(404).json({ error: 'Not found' });
  res.json(note);
});

app.use((err, req, res, next) => {
  console.error(err.message);
  res.status(500).json({ error: 'Something went wrong' });
});

app.listen(3000, () => console.log('Auth demo on http://localhost:3000'));
